nodes = {18,23,26,35,42,62,64,68,80,98,102,149}
window = (22553,34553)
ev = [e for e in events if window[0] <= e[2] <= window[1]]
from collections import defaultdict
inter_by_pair = defaultdict(list)
for u,v,t in ev:
    a,b = min(u,v), max(u,v)
    inter_by_pair[(a,b)].append(t)

pair_times = defaultdict(list)
for (a,b), times in inter_by_pair.items():
    pair_times[(a,b)] = sorted(times)
    pair_times[(b,a)] = sorted(times)

all_nodes = set()
for u,v,t in ev:
    all_nodes.add(u); all_nodes.add(v)
all_nodes = sorted(all_nodes)

matches = []
nodes_list = sorted(nodes)
for i in range(len(nodes_list)):
    for j in range(i+1, len(nodes_list)):
        x = nodes_list[i]; y = nodes_list[j]
        t_xy_list = pair_times.get((x,y), [])
        if not t_xy_list: continue
        for c in all_nodes:
            if c==x or c==y: continue
            t_cx = pair_times.get((c,x), [])
            t_cy = pair_times.get((c,y), [])
            if not t_cx or not t_cy: continue
            for t1 in t_cx:
                for t2 in t_cy:
                    t_shared = max(t1,t2)
                    for t_xy in t_xy_list:
                        if t_xy > t_shared and t_xy - t_shared <= 800:
                            matches.append({'x':x,'y':y,'c':c,'t_cx':t1,'t_cy':t2,'t_xy':t_xy,'t_shared':t_shared})

print('matches', len(matches))
for m in matches:
    print(m)

triples = {(m['x'],m['y'],m['c']) for m in matches}
print('unique triples', len(triples))
for t in sorted(triples):
    print(t)

